"""Wherobots Jobs API Client.

``WherobotsJob`` is the primary user-facing class.  It orchestrates
job submission, monitoring, log streaming, and cancellation by
delegating HTTP work to the ``RunsAPI`` layer.
"""

from __future__ import annotations

import time
from collections.abc import Callable, Iterator
from typing import Any

from wherobots.api.runs import RunsAPI
from wherobots.config import WherobotsConfig
from wherobots.enums import DependencyType, JobStatus, Region, Runtime, is_terminal_status
from wherobots.exceptions import (
    WherobotsAPIError,
    WherobotsJobError,
    WherobotsTimeoutError,
    WherobotsValidationError,
)
from wherobots.models import (
    CreateRunPayload,
    LogsResponse,
    RunEnvironment,
    RunJarPayload,
    RunListPage,
    RunMetricsResponse,
    RunPythonPayload,
    RunView,
    UtilizationStats,
    extract_instant_value,
)
from wherobots.utils.logger import get_logger
from wherobots.utils.validation import validate_name

logger = get_logger("client")


def _status_str(status: JobStatus | str | None) -> str:
    """Human-readable status string for logging, handling the
    forward-compat case where *status* is a raw string the enum
    doesn't know about."""
    if status is None:
        return "UNKNOWN"
    if isinstance(status, JobStatus):
        return status.value
    return status


class WherobotsJob:
    """Wherobots Job Run Manager.

    Manages the lifecycle of Wherobots job runs including submission,
    monitoring, log streaming, and cancellation.

    Use :meth:`from_run_id` to attach to an existing run for read-only
    log/metrics access without binding a script.
    """

    # Candidate metric key names. The metrics endpoint is server-defined
    # and untyped (see ``RunMetricsResponse``); the UPPERCASE names are
    # the current production keys, with lowercase fallbacks kept for
    # forward-compat. Confirmed against run gt3oirei5widjk (2026-06-11).
    _CPU_METRIC_KEYS: tuple[str, ...] = ("CPU_UTILIZATION_PERCENT", "cpu_usage", "cpu")
    _MEM_METRIC_KEYS: tuple[str, ...] = (
        "MEMORY_UTILIZATION_PERCENT",
        "memory_usage",
        "mem_usage",
    )
    _COST_METRIC_KEYS: tuple[str, ...] = ("COST_USD", "cost_usd")
    _SU_METRIC_KEYS: tuple[str, ...] = ("CONSUMED_SPATIAL_UNITS", "consumed_spatial_units")

    # Instance attribute type declarations. ``_init_defaults`` (called
    # by both ``__init__`` and ``from_run_id``) assigns initial values
    # for every name listed here. Adding a new instance attribute means
    # one declaration here + one assignment in ``_init_defaults`` —
    # both constructor paths then pick it up automatically.
    script: str | None
    name: str | None
    runtime: str | None
    region: str | None
    version: str | None
    timeout_seconds: int
    args: list[str]
    spark_configs: dict[str, str]
    dependencies: list[dict[str, Any]]
    spark_driver_disk_gb: int | None
    spark_executor_disk_gb: int | None
    s3_bucket: str | None
    s3_prefix: str | None
    jar_main_class: str | None
    auto_upload: bool
    is_jar: bool
    run_id: str | None
    # Status may be a string when the server returns a value the
    # SDK's JobStatus enum doesn't recognize yet (forward-compat).
    status: JobStatus | str | None
    _last_log_cursor: int | str
    _script_uri: str | None
    _attached: bool
    _config: WherobotsConfig
    _api: RunsAPI

    def __init__(
        self,
        script: str,
        name: str,
        runtime: str | Runtime | None = None,
        region: str | Region | None = None,
        api_key: str | None = None,
        version: str | None = None,
        timeout_seconds: int = 3600,
        args: list[str] | None = None,
        spark_configs: dict[str, str] | None = None,
        dependencies: list[dict[str, Any]] | None = None,
        spark_driver_disk_gb: int | None = None,
        spark_executor_disk_gb: int | None = None,
        s3_bucket: str | None = None,
        s3_prefix: str | None = None,
        jar_main_class: str | None = None,
        auto_upload: bool = True,
        base_url: str | None = None,
        request_timeout_seconds: int | None = None,
        config: WherobotsConfig | None = None,
    ):
        """Initialize a Wherobots Job.

        Args:
            script: Path to Python script (.py) or JAR file (.jar).
                   Can be local path or S3 URI (s3://bucket/key)
            name: Job name (8-255 chars, alphanumeric, _, -, .)
            runtime: The compute runtime to use. Accepts a ``Runtime`` enum
                value or a raw string; strings are passed to the API as-is.
                Override the default runtime set for your organization — only
                set this if you need a specific runtime instead of the one your
                administrator has configured. When omitted, your organization's
                default runtime is used.
            region: The compute region to run in. Accepts a ``Region`` enum
                value or a raw string (e.g. a BYOC region such as
                ``byoc-acme-us-east-1``); strings are passed to the API as-is.
                Override the default region set for your organization — only set
                this if you intend to use a specific region instead of the one
                your administrator has configured. When omitted, your
                organization's default region is used.
            api_key: Wherobots API key (or set WHEROBOTS_API_KEY env var)
            version: Wherobots version ("latest" or "preview")
            timeout_seconds: Job timeout in seconds (default: 3600)
            args: Optional list of arguments to pass to script
            spark_configs: Optional Spark configuration dict
            dependencies: Optional list of PyPI or file dependencies
            spark_driver_disk_gb: Optional driver disk size
            spark_executor_disk_gb: Optional executor disk size
            s3_bucket: Deprecated. Ignored; presigned uploads are used
                instead. Will be removed in a future release.
            s3_prefix: Deprecated. Ignored; presigned uploads are used
                instead. Will be removed in a future release.
            jar_main_class: Main class for JAR files (required for JARs)
            auto_upload: Automatically upload local scripts via presigned
                URL (default: True)
            base_url: Override the API base URL
            request_timeout_seconds: HTTP request timeout in seconds
            config: Optional WherobotsConfig to override defaults

        Raises:
            WherobotsValidationError: If script is None/empty, disk sizes
                are negative, or jar_main_class is missing for JARs.
        """
        if not script:
            raise WherobotsValidationError("script must not be None or empty")

        if spark_driver_disk_gb is not None and spark_driver_disk_gb < 0:
            raise WherobotsValidationError(
                f"spark_driver_disk_gb must be non-negative, got {spark_driver_disk_gb}"
            )
        if spark_executor_disk_gb is not None and spark_executor_disk_gb < 0:
            raise WherobotsValidationError(
                f"spark_executor_disk_gb must be non-negative, got {spark_executor_disk_gb}"
            )

        self._init_defaults()

        region_value = region.value if isinstance(region, Region) else region

        # Deprecation warnings for s3_bucket / s3_prefix are emitted by
        # ``WherobotsConfig.from_env`` so they fire exactly once per
        # construction regardless of whether the user went through
        # ``WherobotsJob`` or ``WherobotsConfig`` directly.
        self._config = config or WherobotsConfig.from_env(
            api_key=api_key,
            region=region_value,
            s3_bucket=s3_bucket,
            s3_prefix=s3_prefix,
            base_url=base_url,
            version=version,
            request_timeout_seconds=request_timeout_seconds,
        )

        self.script = script
        self.name = validate_name(name)
        self.runtime = runtime.value if isinstance(runtime, Runtime) else runtime
        # No hardcoded fallback: when neither the argument nor the config
        # supplies a region, leave it unset so the API applies the org default.
        self.region = region_value or self._config.region
        self.version = version or self._config.version
        self.timeout_seconds = timeout_seconds
        self.args = args or []
        self.spark_configs = spark_configs or {}
        self.dependencies = dependencies or []
        self.spark_driver_disk_gb = spark_driver_disk_gb
        self.spark_executor_disk_gb = spark_executor_disk_gb
        self.s3_bucket = s3_bucket or self._config.s3_bucket
        self.s3_prefix = s3_prefix or self._config.s3_prefix
        self.jar_main_class = jar_main_class
        self.auto_upload = auto_upload

        self.is_jar = script.lower().endswith(".jar")
        if self.is_jar and not jar_main_class:
            raise WherobotsValidationError("jar_main_class is required for JAR files")

        self._api = RunsAPI.from_config(self._config)

    def _init_defaults(self) -> None:
        """Initialize instance attributes shared by every construction path.

        Both ``__init__`` and :meth:`from_run_id` MUST call this first,
        then override the subset of fields they own. Any new instance
        attribute that lives on every ``WherobotsJob`` belongs here
        (and in the class-level type declarations above) — adding it
        in only one constructor would leave the other in a
        partially-constructed state.
        """
        self.script = None
        self.name = None
        self.runtime = None
        self.region = None
        self.version = None
        self.timeout_seconds = 0
        self.args = []
        self.spark_configs = {}
        self.dependencies = []
        self.spark_driver_disk_gb = None
        self.spark_executor_disk_gb = None
        self.s3_bucket = None
        self.s3_prefix = None
        self.jar_main_class = None
        self.auto_upload = False
        self.is_jar = False
        self.run_id = None
        self.status = None
        self._last_log_cursor = 0
        self._script_uri = None
        self._attached = False

    # ------------------------------------------------------------------ #
    # Upload helpers
    # ------------------------------------------------------------------ #

    @staticmethod
    def _is_s3_uri(path: str) -> bool:
        return path.startswith("s3://")

    def _prepare_script_uri(self) -> str:
        """Resolve the script to an S3 URI, uploading if necessary.

        Decision tree:

        1. Already resolved → return cached URI.
        2. Script is already an ``s3://`` URI → use directly.
        3. Local file + ``auto_upload=True`` → upload via the
           STS-credentialed flow (``FilesAPI.upload_managed_file``).
           Only an API key is needed.
        4. ``auto_upload=False`` → error.
        """
        if self._script_uri:
            return self._script_uri

        # Only reachable from submit(), which raises in attached mode
        # before getting here. The asserts narrow ``str | None`` -> ``str``.
        assert self.script is not None, "script must be set in submit-mode"

        if self._is_s3_uri(self.script):
            self._script_uri = self.script
        elif self.auto_upload:
            self._script_uri = self._upload_local_script(self.script)
        else:
            raise WherobotsValidationError(
                f"Script path '{self.script}' is not an S3 URI. "
                "Set auto_upload=True or provide an S3 URI."
            )

        assert self._script_uri is not None  # all branches above set or raise
        return self._script_uri

    def _upload_local_script(self, local_path: str) -> str:
        """Upload a local script to managed storage via STS+boto3.

        Auto-upload is intentionally scoped to managed storage only. If
        you need the script in a Storage Integration, upload it yourself
        via :class:`wherobots.FilesAPI` and pass the resulting ``s3://``
        URI as ``script=...``.

        Args:
            local_path: Path to the local script file to upload.

        Returns:
            The ``s3://`` URI of the uploaded script under managed storage.

        Raises:
            WherobotsAPIError: If the credential fetch or upload fails.
        """
        from wherobots.api.files import FilesAPI

        files_api = FilesAPI.from_config(self._config)
        try:
            s3_uri = files_api.upload_managed_file(local_path, subdir="scripts")
            logger.info("Script upload succeeded: %s", s3_uri)
            return s3_uri
        finally:
            files_api.close()

    def _prepare_dependencies(self) -> None:
        """Resolve any local dependency paths by uploading them.

        Atomic: builds a fully-resolved replacement list in a local
        variable and only swaps it into ``self.dependencies`` after
        every upload succeeds. If any upload raises, the on-instance
        state is left untouched so a retried ``submit()`` will redo
        the work cleanly rather than ship a half-resolved dep set.

        Sentinel ``_pendingUpload`` keys are stripped so the dict
        serializes cleanly into the request body.
        """
        if not any(d.get("_pendingUpload") for d in self.dependencies):
            return
        if not self.auto_upload:
            raise WherobotsValidationError(
                "Local dependency files require auto_upload=True. "
                "Either set auto_upload=True or pre-upload and pass an s3:// URI."
            )
        from wherobots.api.files import FilesAPI

        resolved: list[dict[str, Any]] = []
        files_api = FilesAPI.from_config(self._config)
        try:
            for dep in self.dependencies:
                if not dep.get("_pendingUpload"):
                    resolved.append(dep)
                    continue
                # Build a fresh dict so partial failures don't mutate
                # the original sentinel-tagged entry on self.dependencies.
                new_dep = {k: v for k, v in dep.items() if not k.startswith("_")}
                new_dep["filePath"] = files_api.upload_dependency(dep["filePath"])
                logger.info("Dependency upload succeeded: %s", new_dep["filePath"])
                resolved.append(new_dep)
        finally:
            files_api.close()
        # Only commit on full success — any raise above leaves
        # self.dependencies untouched, so a retry runs the same work.
        self.dependencies = resolved

    # ------------------------------------------------------------------ #
    # Payload construction
    # ------------------------------------------------------------------ #

    def _build_payload(self) -> CreateRunPayload:
        # Only reachable from submit(); attached instances raise earlier.
        # Runtime is optional — the API applies the org default when unset.
        assert self.name is not None, "name must be set in submit-mode"

        self._prepare_dependencies()
        script_uri = self._prepare_script_uri()

        run_python: RunPythonPayload | None = None
        run_jar: RunJarPayload | None = None

        if self.is_jar:
            run_jar = RunJarPayload(
                uri=script_uri,
                main_class=self.jar_main_class or "",
                args=self.args,
            )
        else:
            run_python = RunPythonPayload(uri=script_uri, args=self.args)

        environment: RunEnvironment | None = None
        if (
            self.spark_configs
            or self.dependencies
            or self.spark_driver_disk_gb is not None
            or self.spark_executor_disk_gb is not None
        ):
            environment = RunEnvironment(
                spark_configs=self.spark_configs or None,
                dependencies=self.dependencies or None,
                spark_driver_disk_gb=self.spark_driver_disk_gb,
                spark_executor_disk_gb=self.spark_executor_disk_gb,
            )

        return CreateRunPayload(
            runtime=self.runtime,
            name=self.name,
            version=self.version or "latest",
            timeout_seconds=self.timeout_seconds,
            run_python=run_python,
            run_jar=run_jar,
            environment=environment,
        )

    # ------------------------------------------------------------------ #
    # Attach
    # ------------------------------------------------------------------ #

    @classmethod
    def from_run_id(
        cls,
        run_id: str,
        *,
        api_key: str | None = None,
        config: WherobotsConfig | None = None,
        base_url: str | None = None,
        region: str | None = None,
        request_timeout_seconds: int | None = None,
    ) -> WherobotsJob:
        """Attach to an existing run for read-only log/metric access.

        Unlike the regular constructor this does not require a script
        or name — only a ``run_id``. The returned instance is read-only:
        :meth:`submit` will raise. All other read methods (``get_logs``,
        ``iter_logs``, ``poll_for_logs``, ``get_metrics``,
        ``get_cpu_utilization``, ``get_mem_utilization``, ``get_status``,
        ``cancel``, ``wait_for_completion``) work normally.

        Args:
            run_id: Run identifier from a prior submission, the CLI, or
                the Wherobots UI.
            api_key: Wherobots API key (or set ``WHEROBOTS_API_KEY``).
            config: Pre-built ``WherobotsConfig`` to use instead of the
                environment.
            base_url: Override the API base URL.
            region: AWS region override.
            request_timeout_seconds: HTTP request timeout in seconds.

        Returns:
            A ``WherobotsJob`` bound to *run_id* with descriptive
            fields (name, runtime, status, ...) hydrated from the API.

        Raises:
            WherobotsValidationError: If *run_id* is empty.
            WherobotsAPIError: If the initial refresh fails.
        """
        if not run_id:
            raise WherobotsValidationError("run_id must not be None or empty")

        self = cls.__new__(cls)
        self._init_defaults()

        self._config = config or WherobotsConfig.from_env(
            api_key=api_key,
            region=region,
            base_url=base_url,
            request_timeout_seconds=request_timeout_seconds,
        )
        self._api = RunsAPI.from_config(self._config)

        # Attached-mode overrides on top of _init_defaults().
        self.run_id = run_id
        self._attached = True
        self.region = region or self._config.region
        self.version = self._config.version
        self.s3_bucket = self._config.s3_bucket
        self.s3_prefix = self._config.s3_prefix

        self.refresh()
        return self

    def refresh(self) -> RunView:
        """Re-fetch the run from the API and update local fields.

        Updates ``status``, ``name``, ``runtime``, ``region``, and
        ``version`` in place. Works in both attached and submitted modes.

        Returns:
            The freshly fetched ``RunView``.

        Raises:
            WherobotsJobError: If ``run_id`` is not set.
        """
        if not self.run_id:
            raise WherobotsJobError("No run_id bound. Call submit() or use from_run_id().")
        run_view = self._api.get(self.run_id)
        self.status = run_view.status
        if run_view.name:
            self.name = run_view.name
        if run_view.runtime:
            self.runtime = run_view.runtime
        if run_view.region:
            self.region = run_view.region
        if run_view.version:
            self.version = run_view.version
        return run_view

    # ------------------------------------------------------------------ #
    # Lifecycle
    # ------------------------------------------------------------------ #

    def close(self) -> None:
        """Close the underlying API session.

        Should be called when the job manager is no longer needed,
        or use as a context manager instead.
        """
        self._api.close()

    def __enter__(self) -> WherobotsJob:
        return self

    def __exit__(self, *exc: Any) -> None:
        self.close()

    # ------------------------------------------------------------------ #
    # Public API
    # ------------------------------------------------------------------ #

    def submit(self) -> str:
        """Submit the job run.

        Returns:
            Run ID
        """
        if self._attached:
            raise WherobotsValidationError(
                "Cannot submit a job attached via from_run_id(); this instance is read-only."
            )
        if self.run_id:
            logger.warning("Job already submitted with run_id: %s", self.run_id)
            return self.run_id

        payload = self._build_payload()
        logger.info("Submitting job '%s' to %s", self.name, self.region)

        run_view = self._api.create(payload, region=self.region)
        self.run_id = run_view.id
        self.status = run_view.status

        logger.info("Job submitted successfully. Run ID: %s", self.run_id)
        if self.status:
            logger.info("Status: %s", _status_str(self.status))

        return self.run_id

    def get_status(self) -> RunView:
        """Get current job status and details.

        Returns:
            RunView with full job details
        """
        if not self.run_id:
            raise WherobotsJobError("Job not submitted. Call submit() first.")

        run_view = self._api.get(self.run_id)
        self.status = run_view.status
        return run_view

    def get_logs(
        self,
        cursor: int | str = 0,
        size: int = 100,
    ) -> LogsResponse:
        """Get job logs.

        Args:
            cursor: Position to start reading logs. Accepts integer byte
                offsets (legacy) or string cursors returned in
                ``LogsResponse.next_page``. Defaults to ``0``.
            size: Maximum number of log entries to retrieve (default: 100)

        Returns:
            LogsResponse with items and pagination info
        """
        if not self.run_id:
            raise WherobotsJobError("Job not submitted. Call submit() first.")

        return self._api.get_logs(self.run_id, cursor=cursor, size=size)

    def get_metrics(self) -> RunMetricsResponse:
        """Get job metrics for the run.

        Returns:
            RunMetricsResponse with series and instant metrics
        """
        if not self.run_id:
            raise WherobotsJobError("Job not submitted. Call submit() first.")

        return self._api.get_metrics(self.run_id)

    def get_cpu_utilization(self) -> UtilizationStats:
        """Get aggregated CPU utilization for the run.

        Returns:
            ``UtilizationStats`` with ``latest``/``max``/``avg``/``series``.
            All fields are ``None``/empty when the CPU metric is absent
            from the server response.
        """
        metrics = self.get_metrics()
        return UtilizationStats.from_metric(
            metrics.instant_metrics, metrics.series_metrics, self._CPU_METRIC_KEYS
        )

    def get_mem_utilization(self) -> UtilizationStats:
        """Get aggregated memory utilization for the run.

        Returns:
            ``UtilizationStats`` with ``latest``/``max``/``avg``/``series``.
            All fields are ``None``/empty when the memory metric is
            absent from the server response.
        """
        metrics = self.get_metrics()
        return UtilizationStats.from_metric(
            metrics.instant_metrics, metrics.series_metrics, self._MEM_METRIC_KEYS
        )

    def get_cost(self) -> float | None:
        """Get the run's total cost in USD.

        Returns:
            Cost in USD (e.g. ``16.90``), or ``None`` if the server did
            not surface a cost for this run (typical for runs that are
            still running or have not yet been billed).
        """
        metrics = self.get_metrics()
        return extract_instant_value(metrics.instant_metrics, self._COST_METRIC_KEYS)

    def get_consumed_spatial_units(self) -> float | None:
        """Get the spatial units (SUs) consumed by the run.

        Returns:
            SUs consumed (e.g. ``11.27``), or ``None`` if not reported.
        """
        metrics = self.get_metrics()
        return extract_instant_value(metrics.instant_metrics, self._SU_METRIC_KEYS)

    def iter_logs(
        self,
        cursor: int | str = 0,
        size: int = 100,
        max_pages: int = 10_000,
    ) -> Iterator[dict[str, Any]]:
        """Iterate over log entries until pagination ends.

        Args:
            cursor: Initial pagination cursor.
            size: Page size passed to :meth:`get_logs`.
            max_pages: Hard ceiling on pages fetched, to guard against a
                buggy server that always returns a distinct
                ``next_page`` cursor. Defaults to ``10_000``.

        Raises:
            WherobotsJobError: If the page ceiling is hit.
        """
        next_cursor: int | str = cursor
        for _ in range(max_pages):
            logs = self.get_logs(cursor=next_cursor, size=size)
            for item in logs.items:
                yield item.to_dict()
            if logs.next_page is None or logs.next_page == next_cursor:
                return
            next_cursor = logs.next_page
        raise WherobotsJobError(
            f"iter_logs exceeded max_pages={max_pages} without reaching end of log stream"
        )

    def poll_for_logs(
        self,
        follow: bool = True,
        interval: float = 2.0,
        log_handler: Callable[[dict[str, Any]], None] | None = None,
        max_errors: int = 10,
        _deadline: float | None = None,
    ) -> None:
        """Poll and print job logs.

        Args:
            follow: If True, continue polling until job completes.
            interval: Polling interval in seconds (default: 2.0).
            log_handler: Optional handler for each log item dict.
            max_errors: Max consecutive transient errors before giving up
                (default: 10). Non-transient errors (4xx except 429)
                are raised immediately.
            _deadline: Internal. Monotonic clock deadline for timeout
                enforcement.  Callers should use
                ``wait_for_completion(max_wait_seconds=...)`` instead.

        Raises:
            WherobotsJobError: If the job has not been submitted.
            WherobotsTimeoutError: If *_deadline* is set and exceeded.
            WherobotsAPIError: On non-transient HTTP errors.
        """
        if not self.run_id:
            raise WherobotsJobError("Job not submitted. Call submit() first.")

        def default_handler(item: dict[str, Any]) -> None:
            print(item.get("raw", ""), flush=True)

        handler = log_handler or default_handler
        consecutive_errors = 0

        while True:
            # Enforce timeout when called from wait_for_completion
            if _deadline is not None and time.monotonic() >= _deadline:
                raise WherobotsTimeoutError(
                    f"Timed out waiting for job {self.run_id} "
                    f"(deadline exceeded during log streaming)"
                )

            try:
                prev_cursor = self._last_log_cursor
                logs = self.get_logs(cursor=self._last_log_cursor)

                for item in logs.items:
                    handler(item.to_dict())

                if logs.next_page is not None:
                    self._last_log_cursor = logs.next_page

                consecutive_errors = 0  # Reset on success

                if not follow:
                    # Drain remaining pages, then exit. Mirror iter_logs:
                    # stop when next_page is missing or the cursor doesn't
                    # advance (server-side loop guard).
                    if logs.next_page is None or logs.next_page == prev_cursor:
                        break
                    continue  # fetch the next page immediately, no sleep

                run_view = self.get_status()
                if is_terminal_status(run_view.status):
                    # Drain remaining logs
                    final_logs = self.get_logs(cursor=self._last_log_cursor, size=1000)
                    for item in final_logs.items:
                        handler(item.to_dict())
                    break

                time.sleep(interval)

            except KeyboardInterrupt:
                logger.info("Log streaming interrupted by user")
                break
            except WherobotsAPIError as exc:
                # Non-transient HTTP errors should not be retried
                if exc.status_code and 400 <= exc.status_code < 500 and exc.status_code != 429:
                    raise
                consecutive_errors += 1
                logger.error("Error polling logs (%d/%d): %s", consecutive_errors, max_errors, exc)
                if consecutive_errors >= max_errors:
                    raise
                time.sleep(interval)
            except Exception as exc:
                consecutive_errors += 1
                logger.error("Error polling logs (%d/%d): %s", consecutive_errors, max_errors, exc)
                if consecutive_errors >= max_errors:
                    raise
                time.sleep(interval)

    def cancel(self) -> bool:
        """Cancel the job run.

        Returns:
            True if cancellation request was successful
        """
        if not self.run_id:
            raise WherobotsJobError("Job not submitted. Call submit() first.")

        self._api.cancel(self.run_id)

        logger.info("Cancellation requested for run %s", self.run_id)
        logger.info("It may take a minute for status to change to CANCELLED")

        return True

    def wait_for_completion(
        self,
        poll_interval: float = 5.0,
        stream_logs: bool = True,
        log_interval: float = 2.0,
        max_wait_seconds: float | None = None,
    ) -> JobStatus | str:
        """Wait for job to complete, optionally streaming logs.

        Args:
            poll_interval: Status check interval in seconds (default: 5.0)
            stream_logs: Stream logs while waiting (default: True)
            log_interval: Log polling interval in seconds (default: 2.0)
            max_wait_seconds: Maximum time to wait before raising
                ``WherobotsTimeoutError``.  ``None`` means wait
                indefinitely (default: None).

        Returns:
            Final job status

        Raises:
            WherobotsTimeoutError: If max_wait_seconds is exceeded.
        """
        if not self.run_id:
            raise WherobotsJobError("Job not submitted. Call submit() first.")

        logger.info("Waiting for job %s to complete...", self.run_id)
        start = time.monotonic()

        if stream_logs:
            deadline = start + max_wait_seconds if max_wait_seconds is not None else None
            self.poll_for_logs(follow=True, interval=log_interval, _deadline=deadline)
        else:
            while True:
                if max_wait_seconds is not None:
                    elapsed = time.monotonic() - start
                    if elapsed >= max_wait_seconds:
                        raise WherobotsTimeoutError(
                            f"Timed out waiting for job {self.run_id} "
                            f"after {elapsed:.0f}s (limit: {max_wait_seconds}s)"
                        )
                run_view = self.get_status()
                if is_terminal_status(run_view.status):
                    break
                if run_view.status:
                    logger.info("Status: %s", _status_str(run_view.status))
                time.sleep(poll_interval)

        final_view = self.get_status()
        if not final_view.status:
            raise WherobotsJobError(f"Job {self.run_id} returned an unrecognized status")

        self.status = final_view.status
        logger.info("Job %s finished with status: %s", self.run_id, _status_str(self.status))

        if self.status == JobStatus.FAILED:
            logger.error("Job failed. Check logs for details.")
        elif self.status == JobStatus.CANCELLED:
            logger.warning("Job was cancelled.")

        return self.status

    # ------------------------------------------------------------------ #
    # Class-level helpers (no instance required)
    # ------------------------------------------------------------------ #

    @classmethod
    def list_runs(
        cls,
        api_key: str | None = None,
        region: str | None = None,
        name_pattern: str | None = None,
        created_after: str | None = None,
        status: list[str | JobStatus] | None = None,
        cursor: str | None = None,
        size: int = 50,
        base_url: str | None = None,
        request_timeout_seconds: int | None = None,
        config: WherobotsConfig | None = None,
    ) -> RunListPage:
        """List job runs in the organization.

        Args:
            api_key: Wherobots API key (or use WHEROBOTS_API_KEY env var)
            region: Filter by region
            name_pattern: Filter by name pattern (supports * wildcard)
            created_after: Filter runs created after this ISO timestamp
            status: Filter by status (list of statuses)
            cursor: Pagination cursor
            size: Number of results per page (default: 50, max: 100)
            base_url: Override API base URL
            request_timeout_seconds: HTTP request timeout in seconds
            config: Optional WherobotsConfig to override defaults

        Returns:
            RunListPage with items, total, and pagination cursor
        """
        cfg = config or WherobotsConfig.from_env(
            api_key=api_key,
            region=region,
            base_url=base_url,
            request_timeout_seconds=request_timeout_seconds,
        )

        with RunsAPI.from_config(cfg) as api:
            return api.list(
                region=region or cfg.region,
                name_pattern=name_pattern,
                created_after=created_after,
                status=status,
                cursor=cursor,
                size=size,
            )

    @classmethod
    def add_pypi_dependency(cls, library_name: str, library_version: str) -> dict[str, str]:
        """Create a PyPI dependency object.

        Args:
            library_name: PyPI package name
            library_version: Package version

        Returns:
            Dependency dictionary
        """
        return {
            "sourceType": DependencyType.PYPI.value,
            "libraryName": library_name,
            "libraryVersion": library_version,
        }

    @classmethod
    def add_file_dependency(cls, file_path: str) -> dict[str, Any]:
        """Create a file dependency entry.

        Accepts either an ``s3://`` URI (used as-is) or a local file
        path. Local paths are marked for **lazy upload** at
        ``submit()`` time — auto-upload always targets managed storage.

        Need to upload to a Storage Integration (or a custom subdir)?
        Use :class:`wherobots.FilesAPI` directly to upload, then pass
        the resulting ``s3://`` URI here. Keeps this method focused
        on dependency declaration; :class:`FilesAPI` owns "where files
        go."

        Args:
            file_path: ``s3://...`` URI **or** local filesystem path
                ending in ``.jar``, ``.whl``, ``.zip``, or ``.json``.

        Returns:
            Dependency dictionary. May carry an internal
            ``_pendingUpload`` sentinel when a local path is given;
            it is stripped during request building.

        Raises:
            WherobotsValidationError: If the extension is not one of
                ``.jar`` / ``.whl`` / ``.zip`` / ``.json``.
        """
        valid_extensions = (".jar", ".whl", ".zip", ".json")
        if not file_path.endswith(valid_extensions):
            raise WherobotsValidationError(
                f"File must have one of these extensions: {list(valid_extensions)}"
            )

        if file_path.startswith("s3://"):
            return {
                "sourceType": DependencyType.FILE.value,
                "filePath": file_path,
            }

        return {
            "sourceType": DependencyType.FILE.value,
            "filePath": file_path,
            "_pendingUpload": True,
        }
